 31	    private const RESOURCE_WORDS = 'metal|crystal|deuterium|deut';
 32	
 33	    public function handle(string $text): InboundSocialExchange|null
 34	    {
 35	        $normalised = strtolower(trim(preg_replace('/\s+/', ' ', $text) ?? ''));
 36	
 37	        if ($normalised === '') {
 38	            return null;
 39	        }
 40	
 41	        return $this->compensation($normalised)
 42	            ?? $this->apology($normalised)
 43	            ?? $this->warning($normalised)
 44	            ?? $this->ceasefire($normalised)
 45	            ?? $this->cooperation($normalised)
 46	            ?? $this->trade($normalised)
 47	            ?? $this->acknowledgement($normalised);
 48	    }
 49	
 50	    /**
 51	     * An apology that also promises concrete amends is a compensation offer, not an apology:
 52	     * the offer creates the counterparty commitment that a later delivery fulfils. Harm must
 53	     * be named (the same acknowledgement an apology needs) and the offer must state a
 54	     * resource and an amount, because a promise with nothing promised is just cheap talk.
 55	     */
 56	    private function compensation(string $text): InboundSocialExchange|null
 57	    {
 58	        if (!$this->matches($text, 'compensat\w*|make (it )?up|reimburse|refund|repay|pay (you )?back|will send|sending you')) {
 59	            return null;
 60	        }
 61	
 62	        if (!$this->matches($text, 'attack\w*|raid\w*|hit|crash\w*|fleet|ninja\w*|farm\w*|spy|probe\w*|robbed|stole')) {
 63	            return null;
 64	        }
 65	
 66	        $terms = $this->compensationTerms($text);
 67	        if ($terms === null) {
 68	            return null;
 69	        }
 70	
 71	        return $this->exchange(AiSocialExchangeType::CompensationOffer, [AiSocialTerm::AcknowledgesHarm->value => true, ...$terms]);
 72	    }
 73	
 74	    /**
 75	     * @return array<string, mixed>|null
 76	     */
 77	    private function compensationTerms(string $text): array|null
 78	    {
 79	        preg_match_all('/\b(?:' . self::RESOURCE_WORDS . ')\b/', $text, $resources);
 80	        $resource = $resources[0][0] ?? null;
 81	
 82	        if ($resource === null) {
 83	            return null;
 84	        }
 85	
 86	        preg_match_all('/\d[\d.,]*/', $text, $amounts);
 87	
 88	        foreach ($amounts[0] as $candidate) {
 89	            $amount = $this->number($candidate);
 90	
 91	            if ($amount <= 0) {
 92	                continue;
 93	            }
 94	
 95	            return [
 96	                AiSocialTerm::Resource->value => $this->resource($resource),
 97	                AiSocialTerm::Amount->value => $amount,
 98	            ];
 99	        }
100	
101	        return null;
102	    }
103	
104	    private function apology(string $text): InboundSocialExchange|null
105	    {
106	        if (!$this->matches($text, 'sorry|apolog\w*|my bad|my fault|excuse me')) {
107	            return null;
108	        }
109	
110	        // An apology only acknowledges harm when it names the harm. Inventing the
111	        // acknowledgement on the sender's behalf would skip the one question the module has
112	        // to ask, so an apology that says nothing about what happened is recorded as a
113	        // question back rather than as a repaired relationship.
114	        $acknowledged = $this->matches($text, 'attack\w*|raid\w*|hit|crash\w*|fleet|ninja\w*|farm\w*|spy|probe\w*|robbed|stole');
115	
116	        return $this->exchange(AiSocialExchangeType::Apology, $acknowledged
117	            ? [AiSocialTerm::AcknowledgesHarm->value => true]
118	            : []);
119	    }
120	
121	    private function warning(string $text): InboundSocialExchange|null
122	    {
123	        if (!$this->matches($text, 'stop attacking|or else|you will regret|last warning|back off|leave (me|us) alone|we will (crush|destroy|hunt|wipe)')) {
124	            return null;
125	        }
126	
127	        $coercive = $this->matches($text, 'or else|you will regret|last warning|we will (crush|destroy|hunt|wipe)');
128	
129	        return $this->exchange(AiSocialExchangeType::Warning, $coercive
130	            ? [AiSocialTerm::Coercive->value => true]
131	            : []);
132	    }
133	
134	    private function ceasefire(string $text): InboundSocialExchange|null
135	    {
136	        if (!$this->matches($text, 'ceasefire|cease fire|truce|non[- ]aggression|nap|stop attacking each other')) {
137	            return null;
138	        }
139	
140	        // No expiry is fabricated: the module cannot enforce an agreement through an
141	        // in-game message, so the exchange is recorded and answered honestly instead of
142	        // inventing a term it would then have to keep.
143	        return $this->exchange(AiSocialExchangeType::CeasefireRequest, []);
144	    }
145	
146	    private function cooperation(string $text): InboundSocialExchange|null
147	    {
148	        $scope = $this->firstMatch($text, 'cooperat\w*|work together|team up|join forces|ally with (me|us)|join (my|our) alliance|alliance');
149	
150	        return $scope === null ? null : $this->exchange(AiSocialExchangeType::CooperationRequest, [AiSocialTerm::Scope->value => $scope]);
151	    }
152	
153	    private function trade(string $text): InboundSocialExchange|null
154	    {
155	        if (!$this->matches($text, 'trade|swap|exchange|sell|buy|deal')) {
156	            return null;
157	        }
158	
159	        return $this->exchange(AiSocialExchangeType::TradeOffer, $this->tradeTerms($text));
160	    }
161	
162	    private function acknowledgement(string $text): InboundSocialExchange|null
163	    {
164	        if (mb_strlen($text) > self::MAXIMUM_ACKNOWLEDGEMENT_CHARACTERS) {
165	            return null;
166	        }
167	
168	        if ($this->matches($text, 'hi|hello|hey|greetings|good (morning|afternoon|evening)')) {
169	            return $this->exchange(AiSocialExchangeType::Greeting, []);
170	        }
171	
172	        if ($this->matches($text, 'thanks|thank you|thx|cheers')) {
173	            return $this->exchange(AiSocialExchangeType::Thanks, []);
174	        }
175	
176	        return null;
177	    }
178	
179	    /**
180	     * Trade terms are read only far enough to tell a stated offer from an incomplete one.
181	     * Which resource was offered and which was requested is deliberately not resolved: the
182	     * module cannot complete a trade either way, so guessing the direction would only make
183	     * the recorded reason wrong.
184	     *
185	     * @return array<string, mixed>
186	     */
187	    private function tradeTerms(string $text): array
188	    {
189	        preg_match_all('/\b(?:' . self::RESOURCE_WORDS . ')\b/', $text, $resources);
190	        preg_match_all('/\d[\d.,]*/', $text, $amounts);
191	        $amounts = array_values(array_filter(
192	            $amounts[0],
193	            fn (string $amount): bool => $this->number($amount) > 0,
194	        ));
195	
196	        if (count($resources[0]) < 2 || count($amounts) < 2) {
197	            return [];
198	        }
199	
200	        return [
201	            AiSocialTerm::OfferedResource->value => $this->resource($resources[0][0]),
202	            AiSocialTerm::OfferedAmount->value => $this->number($amounts[0]),
203	            AiSocialTerm::RequestedResource->value => $this->resource($resources[0][1]),
204	            AiSocialTerm::RequestedAmount->value => $this->number($amounts[1]),
205	        ];
206	    }
207	
208	    private function resource(string $word): string
209	    {
210	        return $word === 'deut' ? AiSocialResource::Deuterium->value : $word;
211	    }
212	
213	    private function number(string $value): float
214	    {
215	        return (float) str_replace(',', '', $value);
216	    }
217	
218	    private function matches(string $text, string $pattern): bool
219	    {
220	        return preg_match('/\b(?:' . $pattern . ')\b/', $text) === 1;
221	    }
222	
223	    private function firstMatch(string $text, string $pattern): string|null
224	    {
225	        return preg_match('/\b(?:' . $pattern . ')\b/', $text, $matches) === 1 ? $matches[0] : null;
226	    }
227	
228	    /**
229	     * @param array<string, mixed> $terms
230	     */
231	    private function exchange(AiSocialExchangeType $type, array $terms): InboundSocialExchange
232	    {
233	        return app()->makeWith(InboundSocialExchange::class, ['type' => $type, 'terms' => $terms]);
234	    }
235	}

