use Modules\AI\Tests\Support\Situation;
use OGame\Models\ChatMessage;
use Tests\IsolatedAccountTestCase;

require_once __DIR__ . '/../../Support/Situation.php';

uses(IsolatedAccountTestCase::class);

// SOC-001: the reply protocol is bounded per conversation, not per counterparty for the account's
// whole life. A neighbour who writes again after an earlier exchange is answered again; otherwise the
// account goes permanently silent to every player it has ever talked to, which is the dormancy the
// cohort read shows.
test('a neighbour who writes again after the protocol went quiet is answered again', function (): void {
    $situation = Situation::of($this)
        ->directMessage('hey, are you active? want to trade?')
        ->session();

    $situation->directMessage('hey, still there? want to trade?')->minutesLater(45)->session()
        ->directMessage('hey, we share a system. no attacks between us, we can both grow')->minutesLater(45)->session();

    $replies = ChatMessage::query()
        ->where('sender_id', $this->currentUserId)
        ->where('recipient_id', $situation->neighbour()?->getPlayer()->getId())
        ->count();

    expect($replies)->toBeGreaterThan(1, 'expected a reply to each message, but ' . $situation->account());
});
