71	            ->where('enabled', true)
72	            ->where('player_id', '!=', $senderId)
73	            ->whereIn('player_id', AllianceMember::query()->where('alliance_id', $chatMessage->alliance_id)->select('user_id'))
74	            ->pluck('player_id');
