76	        $recorded = 0;
77	
78	        foreach ($memberIds as $memberId) {
79	            $observation = AiObservation::firstOrCreateAtomically([
80	                'player_id' => $memberId,
81	                'source_type' => AiObservationSource::ChatMessage,
82	                'source_id' => $chatMessage->id,
83	            ], [
84	                'kind' => AiObservationKind::AllianceChatMessageReceived,
85	                'subject_player_id' => $senderId,
86	                'source_time' => $chatMessage->created_at ?? $this->clock->now(),
87	                'observed_at' => $this->clock->now(),
88	            ]);
89	
90	            if ($observation->wasRecentlyCreated) {
91	                $recorded++;
92	            }
93	        }
