 14	
 15	class BuildAuthoredSocialReplyAction
 16	{
 17	    private const REPETITION_COOLDOWN_DELIVERIES = 2;
 18	
 19	    public function __construct(private RandomSource $randomSource)
 20	    {
 21	    }
 22	
 23	    public function handle(AiSocialExchange $exchange, AiProfile $profile): string|null
 24	    {
 25	        if ($exchange->response === null) {
 26	            return null;
 27	        }
 28	
 29	        $lines = $this->replyLines($exchange->type, $exchange->response, $this->stanceFor($exchange));
 30	        $eligibleLines = $this->withoutRecentDeliveredLines($exchange, $lines);
 31	        $index = (int) floor($this->randomSource->unitInterval($profile->random_seed, 'social-exchange:' . $exchange->id . ':' . $exchange->revision) * count($eligibleLines));
 32	        $line = $eligibleLines[$index];
 33	        $amount = $exchange->response_terms[AiSocialTerm::Amount->value] ?? null;
 34	
 35	        return is_int($amount) || is_float($amount) ? str_replace('{amount}', (string) $amount, $line) : $line;
 36	    }
 37	
 38	    /**
 39	     * English is the only supported language, so the variant set is chosen by exchange type
 40	     * alone. A second language means authored content and a selection input, not a
 41	     * configuration value, which is why no locale is carried here.
 42	     *
 43	     * @return list<string>
 44	     */
 45	    private function replyLines(AiSocialExchangeType $type, AiSocialResponse $response, string $stance): array
 46	    {
 47	        return match ($type) {
 48	            AiSocialExchangeType::HelpRequest => $this->helpReplyLines($response),
 49	            AiSocialExchangeType::Apology => $this->apologyReplyLines($response, $stance),
 50	            AiSocialExchangeType::Greeting => $this->greetingReplyLines(),
 51	            AiSocialExchangeType::Thanks => $this->thanksReplyLines(),
 52	            AiSocialExchangeType::TradeOffer => $this->tradeReplyLines($response),
 53	            AiSocialExchangeType::CeasefireRequest => $this->ceasefireReplyLines($response),
 54	            AiSocialExchangeType::Warning => $this->warningReplyLines($response),
 55	            AiSocialExchangeType::CooperationRequest => $this->cooperationReplyLines($response),
 56	            AiSocialExchangeType::CompensationOffer => $this->compensationReplyLines($response),
 57	            AiSocialExchangeType::AttackerNotice => $this->attackerNoticeLines(),
 58	            AiSocialExchangeType::TransportThanks => $this->transportThanksLines(),
 59	        };
 60	    }
 61	
 62	    /**
 63	     * @param list<string> $lines
 64	     * @return list<string>
 65	     */
 66	    private function withoutRecentDeliveredLines(AiSocialExchange $exchange, array $lines): array
 67	    {
 68	        $recentLines = AiConversationReply::query()
 69	            ->where('player_id', $exchange->player_id)
 70	            ->where('counterparty_player_id', $exchange->counterparty_player_id)
 71	            ->where('state', AiConversationReplyState::Delivered)
 72	            ->latest('delivered_at')
 73	            ->limit(self::REPETITION_COOLDOWN_DELIVERIES)
 74	            ->pluck('message')
 75	            ->all();
 76	        $eligibleLines = array_values(array_filter($lines, fn (string $line): bool => !in_array($line, $recentLines, true)));
 77	
 78	        return $eligibleLines === [] ? $lines : $eligibleLines;
 79	    }
 80	
 81	    /**
 82	     * @return list<string>
 83	     */
 84	    private function helpReplyLines(AiSocialResponse $response): array
 85	    {
 86	        return match ($response) {
 87	            AiSocialResponse::Accept => ['I can help with the requested amount.', 'Your request is accepted; I will provide the agreed amount.'],
 88	            AiSocialResponse::Reject => ['I cannot accept this request.', 'I must decline this request for now.'],
 89	            AiSocialResponse::Counter => ['I can only offer {amount}.', 'I cannot meet the full request; I can offer {amount}.'],
 90	            AiSocialResponse::Clarify => ['Please confirm the amount and terms.', 'I need clearer terms before I can respond.'],
 91	        };
 92	    }
 93	
 94	    /**
 95	     * @return list<string>
 96	     */
 97	    private function apologyReplyLines(AiSocialResponse $response, string $stance): array
 98	    {
 99	        return match ($response) {
100	            AiSocialResponse::Accept => $stance === 'friend'
101	                ? ['Apology accepted — we can move past this.', 'Thank you for saying that. Let us put it behind us.']
102	                : ['I accept your apology, but I remember what happened.', 'Your apology is acknowledged; trust will take time to rebuild.'],
103	            AiSocialResponse::Reject => $stance === 'foe'
104	                ? ['Keep your distance until the threat is gone.', 'Words will not undo this. Stay away.']
105	                : ['An apology alone does not repair this harm.', 'I cannot accept this apology while the threat remains.'],
106	            AiSocialResponse::Counter => $stance === 'friend'
107	                ? ['What will you do to make this right?', 'Tell me how you intend to repair it.']
108	                : ['I need a concrete repair before we can move forward.', 'Show how you will repair this harm first.'],
109	            AiSocialResponse::Clarify => ['Please acknowledge the harm and explain how you will repair it.', 'I need a clearer acknowledgment before we discuss forgiveness.'],
110	        };
111	    }
112	
113	    /**
114	     * A coarse stance for wording only: the same decision to a friend and a foe is worded
115	     * differently, but the decision itself is never changed here. Thresholds mirror the
116	     * cognition gates — threat 0.75 is the refuse line, trust 0.5 the forgiveness floor.
117	     */
118	    private function stanceFor(AiSocialExchange $exchange): string
119	    {
120	        $relationship = AiRelationship::query()
121	            ->where('player_id', $exchange->player_id)
122	            ->where('other_player_id', $exchange->counterparty_player_id)
123	            ->first();
124	
125	        if ((float) $relationship?->threat >= 0.75) {
126	            return 'foe';
127	        }
128	
129	        if ((float) $relationship?->trust >= 0.5) {
130	            return 'friend';
131	        }
132	
133	        return 'neutral';
134	    }
135	
136	    /** @return list<string> */
137	    private function greetingReplyLines(): array
138	    {
139	        return ['Greetings.', 'Hello.'];
140	    }
141	
142	    /** @return list<string> */
143	    private function thanksReplyLines(): array
144	    {
145	        return ['You are welcome.', 'Acknowledged.'];
146	    }
147	
