152	            AiSocialResponse::Clarify => ['Please state both resources and exact amounts.'],
153	            AiSocialResponse::Reject => ['I cannot authorize a trade without a validated transport path.'],
154	            AiSocialResponse::Accept, AiSocialResponse::Counter => ['I cannot authorize this trade.'],
155	        };
156	    }
